  justify-content: center;
  max-width: 800px;
}

.gb-shift-column-title {
  font-family: var(--gb-font-display);
  font-size: clamp(1.25rem, 2.5vw, 1.5rem);
  font-weight: 700;
  color: var(--gb-text-primary);
  margin-bottom: 1.25rem;
}

.gb-shift-from,
.gb-shift-to {
  padding: 0;
}

.gb-shift-list {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.gb-shift-list li {
  font-size: clamp(1rem, 1.5vw, 1.125rem);
  color: var(--gb-text-secondary);
  line-height: 1.6;
  padding-left: 1.25rem;
  position: relative;
}

.gb-shift-list li::before {
  content: '>';
  position: absolute;
  left: 0;
  color: var(--gb-text-muted);
  font-weight: 400;
}

.gb-shift-to .gb-shift-list li {
  font-weight: 600;
  color: var(--gb-text-primary);
}

.gb-shift-arrow-container {
  display: flex;
  align-items: center;
  justify-content: center;
  padding-top: 2rem;
}

.gb-shift-arrow-img {
  width: 100px;
  height: auto;
  opacity: 0.5;
  transform: rotate(-90deg);
}

.gb-shift-icons-row {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2rem;
  margin: 3rem 0 2rem;
  padding-top: 2rem;
}

.gb-shift-icons-img {
  max-width: 900px;
  width: 100%;
  height: auto;
}

.gb-shift-icons-labels {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  max-width: 900px;
  width: 100%;
  position: relative;
}

/* Dotted line connecting icons */
.gb-shift-icons-labels::before {
  content: '';
  position: absolute;
  top: -4.5rem;
  left: 10%;
  right: 10%;
  height: 1px;
  border-top: 2px dotted var(--gb-border);
}

.gb-shift-icons-labels span {
  flex: 1;
  font-size: clamp(1rem, 1.5vw, 1.125rem);
  color: var(--gb-text-muted);
  line-height: 1.6;
  text-align: center;
  max-width: 250px;
}

.gb-shift-footer {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2rem;
  margin-top: 2rem;
  padding-top: 1.5rem;
  border-top: 1px solid var(--gb-border);
}

.gb-shift-footer-heading {
  font-size: clamp(1rem, 1.5vw, 1.125rem);
  color: var(--gb-text-primary);
  font-weight: 600;
  margin-bottom: 0.75rem;
}

.gb-shift-footer-list {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.gb-shift-footer-list li {
  font-size: clamp(0.9375rem, 1.25vw, 1rem);
  color: var(--gb-text-secondary);
  padding-left: 1rem;
  position: relative;
  line-height: 1.6;
}

.gb-shift-footer-list li::before {
  content: '>';
  position: absolute;
  left: 0;
  color: var(--gb-text-muted);
}

.gb-shift-footer-right p {
  font-size: clamp(1rem, 1.5vw, 1.125rem);
  color: var(--gb-text-secondary);
  line-height: 1.7;
  margin: 0;
}


@media (max-width: 768px) {
  .gb-shift-comparison {
    grid-template-columns: 1fr;
    gap: 1.5rem;
    max-width: 320px;
    margin-left: auto;
    margin-right: auto;
  }

  .gb-shift-from,
  .gb-shift-to {
    text-align: left;
  }

  .gb-shift-arrow-container {
    display: flex;
    justify-content: center;
    padding: 1rem 0;
