}

/* Reveal animations */
.gb-reveal {
  opacity: 0;
  transform: translateY(40px);
  transition:
    opacity var(--gb-duration-normal) var(--gb-ease-out-expo),
    transform var(--gb-duration-normal) var(--gb-ease-out-expo);
}

.gb-reveal.visible {
  opacity: 1;
  transform: translateY(0);
}

@media (prefers-reduced-motion: reduce) {
  .gb-reveal {
